import json, math
d = json.load(open('outputs/points-model.json', encoding='utf-8'))
def f(n): return f"{round(n):,}".replace(',', ' ') + ' ₽'
def k(n): return f"{round(n/1000):,}".replace(',', ' ') + ' тыс ₽'
def pct(n): return (f"{round(n*10)/10}".replace('.', ',')) + ' %'
pos, order = d['pos'], d['order']
sk, skAlt, trip, check, rw = d['showerKeepMain'], d['showerKeepAlt'], d['trip'], d['check'], d['reward']
S = {n: {m: d[f'{n}|{m}'] for m in ('yauza', 'melnitsa')} for n in ('осторожный', 'базовый', 'сильный')}
base = S['базовый']['yauza']
orders_year = sum(r['orders'] for r in base['rows'])
mel = S['базовый']['melnitsa']
